def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[[0]*w for _ in range(h)]
    horizontal=any(all(x==4 for x in row) for row in grid)
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0,4):
                if horizontal:
                    out[r][w-1 if c<(w-1)/2 else 0]=grid[r][c]
                else:
                    out[h-1 if r<(h-1)/2 else 0][c]=grid[r][c]
    return out

